import{icon,knot,sprig}from'./hud-icons.js';
export function createHudEditor({widgets,resetInput}){
 const dialog=document.querySelector('#controlsDialog'),head=dialog.querySelector('.dialog-head');head.querySelector('h2').textContent='UI 自訂設定';head.insertAdjacentHTML('beforeend',knot()+sprig());
 const form=document.createElement('section');form.className='hud-editor-form';form.innerHTML='<p class="hud-editor-intro">選擇介面，或直接拖曳畫面上的金框。依你的習慣，留一點空間給風景。</p><label>調整項目<select id="hudTarget">'+widgets.map(w=>'<option value="'+w.id+'">'+w.name+'</option>').join('')+'</select></label><div class="hud-adjust-grid">'+[['X','左右位置',0,100,1],['Y','上下位置',0,100,1],['Scale','大小',40,150,1],['Opacity','不透明度',0,100,1]].map(([key,label,min,max,step])=>'<label>'+label+'<output id="hud'+key+'Value"></output><input id="hud'+key+'" type="range" min="'+min+'" max="'+max+'" step="'+step+'"></label>').join('')+'</div><div class="hud-editor-actions"><button id="hudResetOne">還原此項</button><button id="hudResetAll">全部還原</button><button id="hudApply">完成</button></div><small class="hud-saved" role="status">調整會自動保存在這台裝置 · U 開關設定</small>';
 head.after(form);const details=document.createElement('details');details.className='hud-other-settings';details.innerHTML='<summary>'+icon('music')+' 音樂與散步動作</summary>';while(form.nextSibling)details.append(form.nextSibling);dialog.append(details);
 const selection=document.createElement('div');selection.id='hudSelection';selection.innerHTML='<span></span><i></i>';document.body.append(selection);
 const storageKey='inari-hud-v36',configs={wide:{},compact:{}};let editing=false,selected=widgets[0].id,drag=null;
 const profile=()=>innerWidth<700||innerHeight<560?'compact':'wide';
 try{const saved=JSON.parse(localStorage.getItem(storageKey)||'{}');for(const profile of ['wide','compact'])for(const w of widgets){const c=saved[profile]?.[w.id];if(c&&['x','y','scale','opacity'].every(k=>Number.isFinite(c[k])))configs[profile][w.id]={x:clamp(c.x,0,100),y:clamp(c.y,0,100),scale:clamp(c.scale,40,150),opacity:clamp(c.opacity,0,100)}}}catch{}
 function clamp(x,a,b){return Math.max(a,Math.min(b,x))}
 function config(w){return configs[profile()][w.id]||{...w.defaults(profile())}}
 function save(){try{localStorage.setItem(storageKey,JSON.stringify(configs));form.querySelector('.hud-saved').textContent='已儲存 · U 開關設定'}catch{form.querySelector('.hud-saved').textContent='本次調整已套用'}}
 function apply(){for(const w of widgets){const c=config(w),width=w.element.offsetWidth,height=w.element.offsetHeight,scale=Math.min(c.scale/100,(innerWidth-24)/width,(innerHeight-24)/height),x=12+Math.max(0,innerWidth-24-width*scale)*c.x/100,y=12+Math.max(0,innerHeight-24-height*scale)*c.y/100;w.element.style.setProperty('--hud-x',x+'px');w.element.style.setProperty('--hud-y',y+'px');w.element.style.setProperty('--hud-scale',scale);w.element.style.setProperty('--hud-opacity',c.opacity/100);w.applied={x,y,width:width*scale,height:height*scale,scale,opacity:c.opacity/100}}if(editing)highlight()}
 function current(){return widgets.find(w=>w.id===selected)}
 function highlight(){const w=current();if(!w)return;const r=w.applied;selection.style.cssText='left:'+r.x+'px;top:'+r.y+'px;width:'+r.width+'px;height:'+r.height+'px';selection.querySelector('span').textContent=w.name;selection.hidden=!editing;for(const widget of widgets)widget.element.classList.toggle('hud-selected',editing&&widget===w)}
 function sync(){for(const w of widgets)w.element.classList.toggle('hud-selected',editing&&w.id===selected);apply();const w=current(),c=config(w);document.querySelector('#hudTarget').value=selected;for(const[key,prop]of[['X','x'],['Y','y'],['Scale','scale'],['Opacity','opacity']]){document.querySelector('#hud'+key).value=c[prop];document.querySelector('#hud'+key+'Value').textContent=Math.round(c[prop])+'%'}highlight();dock()}
 function dock(){if(!editing)return;const r=current().applied,compact=profile()==='compact';dialog.classList.toggle('hud-dock-right',!compact&&r.x+r.width/2<innerWidth*.5);dialog.classList.toggle('hud-dock-top',compact&&r.y+r.height/2>innerHeight*.5)}
 function open(){if(dialog.open){dialog.close();return}resetInput();editing=true;document.body.classList.add('hud-editing');dialog.show();apply();sync();document.querySelector('#hudTarget').focus({preventScroll:true})}
 function close(){editing=false;drag=null;selection.hidden=true;document.body.classList.remove('hud-editing');widgets.forEach(w=>w.element.classList.remove('hud-selected'));resetInput()}
 dialog.addEventListener('close',close);document.querySelector('#controlSettings').onclick=open;
 document.querySelector('#hudTarget').onchange=e=>{selected=e.target.value;sync()};
 for(const[key,prop]of[['X','x'],['Y','y'],['Scale','scale'],['Opacity','opacity']])document.querySelector('#hud'+key).oninput=e=>{const w=current();configs[profile()][w.id]={...config(w),[prop]:+e.target.value};apply();sync();save()};
 document.querySelector('#hudResetOne').onclick=()=>{delete configs[profile()][selected];apply();sync();save()};document.querySelector('#hudResetAll').onclick=()=>{configs.wide={};configs.compact={};apply();sync();save()};document.querySelector('#hudApply').onclick=()=>dialog.close();
 document.addEventListener('keydown',e=>{if(e.code==='Escape'&&editing){e.preventDefault();e.stopImmediatePropagation();dialog.close();return}if(e.code==='KeyU'&&!e.repeat&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!(document.activeElement?.tagName==='TEXTAREA'||document.activeElement?.tagName==='INPUT'&&document.activeElement.type!=='range'||document.activeElement?.tagName==='SELECT'&&!editing)&&(!document.querySelector('dialog[open]')||editing)){e.preventDefault();e.stopImmediatePropagation();open()}},true);
 document.addEventListener('pointerdown',e=>{if(!editing||dialog.contains(e.target))return;const w=widgets.find(w=>w.element.contains(e.target));e.preventDefault();e.stopImmediatePropagation();if(!w)return;selected=w.id;const r=w.applied;drag={id:e.pointerId,dx:e.clientX-r.x,dy:e.clientY-r.y,width:r.width,height:r.height};resetInput();sync()},true);
 document.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;e.preventDefault();e.stopImmediatePropagation();const w=current(),x=clamp((e.clientX-drag.dx-12)/Math.max(1,innerWidth-24-drag.width)*100,0,100),y=clamp((e.clientY-drag.dy-12)/Math.max(1,innerHeight-24-drag.height)*100,0,100);configs[profile()][w.id]={...config(w),x,y};apply();sync()},{capture:true,passive:false});
 for(const name of ['pointerup','pointercancel'])document.addEventListener(name,e=>{if(drag&&e.pointerId===drag.id){drag=null;save();e.preventDefault();e.stopImmediatePropagation()}},true);
 document.querySelector('#scene').addEventListener('wheel',e=>{if(editing){e.preventDefault();e.stopImmediatePropagation()}},{capture:true,passive:false});
 for(const w of widgets){w.element.classList.add('hud-widget');w.element.dataset.hudWidget=w.id}selection.hidden=true;addEventListener('resize',()=>{apply();if(editing)sync()});apply();
 return{open,apply,get editing(){return editing&&dialog.open},get selected(){return selected},get stats(){return{profile:profile(),editing:editing&&dialog.open,selected,widgets:Object.fromEntries(widgets.map(w=>[w.id,{config:config(w),...w.applied}]))}}};
}
